#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
import argparse, collections, hashlib, json, shutil

ap=argparse.ArgumentParser(); ap.add_argument('--root',type=Path,required=True); a=ap.parse_args(); R=a.root.resolve()
def canon(o): return json.dumps(o,sort_keys=True,separators=(',',':')).encode()
def sem(o): return hashlib.sha256(canon(o)).hexdigest()
def fsha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
