assert wi['state_before_semantic_sha256']=='ba4e37e48c856f8966fd86540daab423468c551289856517aacc35cc1403c8f3'
assert wi['state_after_semantic_sha256']=='b71eb0509a99016a1718aa2f03ba19193c9b88ef359b47898c3d3517127e9a5f'

outcomes=[]; chain=[]; online_summaries=[]; cross_summaries=[]; processes=[]
online_terms=[]; cross_terms=[]; mechanisms=[]; formula=[]; absence=[]
previous={'dynamic':'30227f09a28c318ea392ae0473cc7644c294ea02aac6007d30eaddd1884ee348','generalized':wi['state_after_semantic_sha256'],'registry':'6663a3a3036199de684255c622690ebf00e02b7e5fd0249af6bbafcfece42cdd','raw_mechanisms':'6746258d7e045c211596ec264a1bcf9a748357e6b7a8f76008e532e189179f1f'}
prev_counts={'dynamic':180,'generalized':10619,'registry':96,'raw_mechanisms':96,'total':12259}
for i in range(90,102):
 d=R/'cegar'/f'iter{i}'; o=load(d/'iteration_outcome.json'); c=load(d/'state_commit_complete.json'); g=load(d/'generalization/summary.json'); x=load(d/'cross_registry/summary.json'); dv=load(d/'direct_verification.json'); outer=load(d/'outer_result.json'); replay=load(d/'outer_independent_replay.json'); aa=load(d/'direct_absence_attempt.json')
 assert o['iteration']==i and o['fresh_outer_process'] and o['outer_status']==outer['status']=='SAT'
 assert replay['status']=='PASS' and replay['parsed_ordered_assertions_equal'] and replay['serialized_formula_fixed_model_status']=='SAT'
 assert all(dv['sectors'][s]['status']=='SATISFIABLE' and dv['sectors'][s]['all_dimacs_clauses_satisfied'] for s in ('Xerr','Zerr'))
 assert o['raw_replay_passed'] and all(o['all_dimacs_clauses_satisfied'].values()) and not o['branch_closed'] and not o['repair_entered'] and o['accepted_absence_proofs']==0
 assert aa['solver_status']=='SAT' and not aa['absence_accepted']
