dump('cegar/summary.json',cegar_summary); dump('cegar/iteration_state_chain.json',{'schema':'round80-state-chain-v1','status':'PASS','pre_outer_transition':'whole_registry/hitting_synthesis/install_result.json','iterations':chain,'next_iteration':102,'final_semantic_sha256':previous})
dump('classification/round80_online_retained_terms.json',{'schema':'round80-online-retained-terms-aggregate-v1','terms':online_terms}); dump('classification/round80_mechanisms.json',{'schema':'round80-source-mechanisms-aggregate-v1','mechanisms':mechanisms}); dump('classification/round80_formula_raw_replay_bindings.json',{'schema':'round80-formula-raw-replay-bindings-aggregate-v1','records':formula})
classification_summary={'schema':'round80-online-generalization-aggregate-summary-v1','status':'PASS','iteration_range':[90,101],'source_mechanisms':24,'formula_assignment_raw_replays':24,'candidate_exact_blocks_preserved':24,'reviewed_generalized_terms_at_start':10595,'pre_outer_whole_registry_terms':24,'online_retained_terms':len(online_terms),'post_outer_cross_registry_terms':len(cross_terms),'round80_generalized_additions':24+len(online_terms)+len(cross_terms),'final_installed_generalized_terms':prev_counts['generalized'],**online_agg,'retained_deletion_controls':sum(len(t.get('deletion_controls',[])) for t in online_terms),'retained_relation_kinds':dict(sorted(collections.Counter(t['relation_kind'] for t in online_terms).items())),'literal_plus_factorized_tuples':online_agg['literal_retained_tuple_replays']+online_agg['factorized_symbolically_proved_tuples'],'claim_scope':'constructive positive sound online generalization; no absence, completeness, exhaustion, repair, or D-star closure claim','zero_truth_cells_used_as_absence':0,'positive_finder_misses_used_as_absence':0,'deletion_countertuples_used_as_absence':0}
dump('classification/summary.json',classification_summary)
dump('cross_registry/round80_cross_registry_retained_terms.json',{'schema':'round80-cross-registry-retained-terms-aggregate-v1','terms':cross_terms})
xsummary={'schema':'round80-cross-registry-aggregate-summary-v1','status':'PASS','batch_range':['post090','post101'],'batch_count':12,'source_registry_range':[98,120],'pre_outer_retained_terms':0,'post_outer_retained_terms':len(cross_terms),'retained_terms_total':len(cross_terms),**cross_agg,'retained_deletion_controls':sum(len(t.get('deletion_controls',[])) for t in cross_terms),'retained_relation_kinds':dict(sorted(collections.Counter(t['relation_kind'] for t in cross_terms).items())),'batches':[{'batch_id':x['batch_id'],'registry':x['registry_count_unchanged'],'raw_candidates':x['raw_candidates'],'retained':x['retained_increment'],'literal_pair_tuples':x['literal_pair_tuples_replayed'],'factorized_multi_tuples':x['factorized_multi_tuples_proved']} for x in cross_summaries],'claim_scope':'constructive cross-registry sound order regions; semantic dedup/dominance against each full evolving library; no absence, completeness, global minimality, repair, exhaustion, or D-star inference','zero_cells_used_as_absence':0,'negative_completion_misses_used_as_absence':0,'deletion_countertuples_used_as_absence':0}
dump('cross_registry/summary.json',xsummary)

